// Transforma o evento do ERP em uma mensagem de alerta legível.
const ev = $input.first().json.body;
const d = ev.data || {};
const brl = (v) => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const textos = {
  'stock.below_reorder_point': () => `⚠️ Estoque baixo: ${d.material?.code} (${d.material?.description}) no ${d.plant?.code} — disponível ${d.available_qty}, ponto ${d.reorder_point}. Avisar Compras.`,
  'purchase_requisition.created': () => `🧾 Requisição ${d.number} criada no ${d.plant?.code} (${d.source}), estimado ${brl(d.estimated_value)}. Aguarda aprovação.`,
  'purchase_order.approved': () => `✅ Pedido de compra ${d.number} aprovado${d.auto_approved ? ' automaticamente' : ''}: ${d.supplier?.name}, ${brl(d.total_gross)}, entrega ${d.delivery_date}.`,
  'goods_receipt.posted': () => `📦 Recebimento ${d.doc_number} do pedido ${d.purchase_order?.number} (${d.purchase_order?.status}).`,
  'sales_order.created': () => `🛒 Pedido de venda ${d.number} para ${d.customer?.name}: ${brl(d.total_gross)}.`,
  'sales_order.confirmed': () => `🔒 Pedido de venda ${d.number} confirmado (${d.fully_confirmed ? 'total' : 'parcial'}).`,
  'delivery.posted': () => `🚚 Entrega ${d.number} saiu (documento ${d.material_doc_number}) — pedido ${d.sales_order?.number}.`,
  'billing.created': () => `💰 Fatura ${d.number} para ${d.customer?.name}: ${brl(d.total_gross)}, vence ${d.due_date}.`,
  'integration.ping': () => `🔔 Teste de conexão do ERP recebido (${d.requested_by}).`,
};
const mensagem = (textos[ev.type] || (() => `Evento ${ev.type} recebido.`))();
return [{ json: { evento: ev.type, evento_id: ev.id, ocorreu_em: ev.occurred_at, mensagem, assinatura_valida: true } }];
